WITH source_rows (
    sequence_label,
    title,
    technology_type,
    applicant_count,
    application_date,
    target_field,
    application_no,
    registration_no,
    valid_until,
    summary
) AS (
    VALUES
    ('개발', '지붕우수 활용을 위한 조립식 합성수지 터널박스와 점검구형 전처리조로 구성된 지중 빗물이용시설 시공방법', '신기술', 3, '20200731', '상하수도', NULL, '제894호', '20280730', '∘이 신기술은 지붕우수 활용을 위해 동일한 현상을 갖는 4개의 다공성 조립형 블록을 암수 맞물림 결합으로 조립하고 합성수지 터널박스를 전후/좌우/상하방향으로 연결하여 조립한 빗물저류조와 유입수 분산판, 침전 분리부, 미세여과 처리장치를 통해 여과 및 침전 분리하여 빗물저류조로 유출하며, 저류된 우수 조경 용수로 재이용할 수 있고 지상과 연결된 점검통로가 있는 점검구형 전처리조로 구성된 지중 빗물이용시설 시공방법이다.'),
    ('개발', 'I형과 박스형 복합단면구조 및 지점부 이중합성구조를 적용한 강합성거더 공법', '신기술', 5, '20210924', '도로', NULL, '제919호', '20290923', '∘이 신기술은 경간 중앙부에는 강I형 단면을 적용하고 지정부는 폐합 강박스 단면을 적용한 복합거더 형식으로 거더의 고정하중을 줄였고, 2개의 강I형 거더를 단일 블록화 하였으며, 지전부 하부플랜지 상면에 일정 두께로 콘크리트를 타설한 이중합성 교량 기술임'),
    ('개발', '앵커콘과 주름형 폐합지수판을 사용한 조립식 프리캐스트 콘크리트 공동구 시공 기술 (KC System)', '신기술', 4, '20221230', '상하수도', NULL, '제953호', '20301229', '∘이 신기술은 지하 환경의 미세거동과 부등침하에 대응하기 위하여 강연선의 양방향 단방향 , 정착 앵커콘과 접합부 누수에 대비가 가능한 주름형 폐합지수판 무수축 , 몰탈을 적용하고 페로니켈 슬 래그가 혼합된 프리캐스트 콘크리트 공동구를 연결 시공하는 조립식 시스템 공법이다.'),
    ('개발', '강재거더에 도입된 프리스트레스력을 단면보강재를 사용하여 유지시키는 가설교량 제작방법(TRM공법)', '신기술', 3, '20250321', '도로', NULL, '제1017호', '20330320', '∘이 신기술은 I형 강재거더에 선행하중인 프리스트레스력을 도입하고 거더 내부에 L형 보강재를 용접하여 프리스트레스력을 유지시킴과 동시에, 보강재 설치에 따른 단면강성 증대를 통해 부재의 구조효율성을 높임으로써 교량의 내하력을 증대시키는 가설교량 제작방법이다'),
    ('개발', '탈착식 보조파일을 이용한 PHC파일 공삭공 시공기술', '신기술', 5, '20250611', '도로', NULL, '제1022호', '20330610', '∘이 신기술은 레버 체결용 고리가 형성된 마감판을 본말뚝인 PHC파일 두부에 PC너트선을 활용하여 볼트체결하고 서비스홀에 두부가 노출되게 관입 배치한 다음에 탈착식 보조파일을 인양하여 본말뚝의 마감판 상부에 안착시키고, 보조파일 내부 기어작동축을 회전시켜 레버를 고리에 회전 체결하여 일체화한 후에 일체화된 보조파일과 본말뚝을 인양하여 천공홀에 관입 및 안착시키고 경타 및 관입량 측정 후에 보조파일 내부 기어 작동축을 회전시켜 레버를 고리로부터 회전 분리한 다음에 본말뚝으로부터 탈거된 보조파일을 인양하는 공삭공 시공기술이다.'),
    ('1', '우수토실 감시경보시스템 ', '특허', 1, '20060711', '상하수도', '제10-2006-0064848호', '제0803700호', '20260711', '∘우수토실월류여부를 감시하고 이를 이동통신중계기를 이용하여 하수처리장 중앙제어장치로 전송하여 우수토실의 월류여부를 실시간으로 감시할수있는 우수토실 감시경보시스템에 관한 것으로 우수토실내부에 설치되어 우수토실월류여부를 감지하는 센서가 구비된 초음파수위계와 상기초음파수위계로부터 전용선을 통해신호를 전송받아처리하고 송신하는 통신제어장치를 포함하여 구성된 우수토실감시장치와, 상기우수토실감시장치에서 송신된 신호를 중계하는 이동통신중계기와, 상기이동통신중계기로부터 신호를 전송받아 월류된우수토실에대한 정보를 처리하고 경고하는 월류경보장치를 포함하여 구성되는 우수토실감시경보시스템을 제공한다.'),
    ('2', '침전지용 핀플럭 제거장치', '특허', 1, '20060807', '상하수도', '제10-2006-0074231호', '제0787406호', '20260807', '∘하수중에 포함된 오염물질의 제거를 목적으로 하수처리용 침전지의 웨어에 설치되는 핀플럭제거장치에 관한것으로서 기존의 침전지의 웨어에 간편히 설치될 수 있고 여과시설등 별도의 추가시설을 설치하지 않고도 BOD,SS농도를 낮출수 있으며 적은비용으로 개량이 가능하다. 핀플럭을 여과시킬수있는 미세스크린과 핀플럭이 상기미세스크린에 다량부착되어 손실수두가 커질때 상기미세스크린을 주기적으로 세정할수있는 세정기를 포함하여구성된침전지용핀플럭제거장치를제공함을그목적으로한다.'),
    ('3', '진공흡입식 스컴제거장치 ', '특허', 1, '20060808', '상하수도', '제10-2006-0074746호', '제0797564호', '20260808', '∘침전지의 수면에 설치되며, 저면에는 다수의 스컴흡입구가 형성된 스컴흡입관과, 이 스컴 흡입관에 연결관으로 연결되며, 흡입력을 제공제공하는 진공탱크 및 진공탱크로부터 공급되는 스컴 및 처리수를 수용하는 스컴용기와, 이 스컴용기 내부에 경사지게 설치되어 스컴을 여과하는 스크린과, 이 스크린의 상측에 설치되어 스컴이 부착된 스크린에 진동을 가하는 진동모터가 구비되는 스컴분리부를 포함하는 진공흡입식 스킴제거장치를 제공한다. 이와같이 구성된 발명에 의하면, 처리수의 수면에 존재하는 스컴을 진공에 의한 흡입력을 이용하여 용이하게 수집 제거할 수 있고, 스컴이 제거된 상태의 처리수를 침전지와 연결된 회수관을 통해 다시 침전지로 회수 가능하게 함으로써 스컴 제거시에 수반되는 약품의 양을 감소시켜 유지관리비를 절감할 수 있게 된다.'),
    ('4', '오리피스 게이트형 유량조절장치 ', '특허', 1, '20061219', '상하수도', '제10-2006-0129795호', '제0787405호', '20261219', '∘하수처리장등에 설치되는 유량조절장치에 관한 것으로 특히 하수처리장으로 유입되는 하수의 양을 자동으로 조절함으로써 하수의 역류현상이나 과부하를 방지하여 설정된 하수량만을 하수처리장으로 유입시킬수있도록 한 오리피스형 유량조절장치에 관한것이다. 이 발명은 맨홀내에 유입되는 하수량의 변동에 따라 상기맨홀내의 게이트를 자동으로 개폐할수있도록 함으로써 하수처리장으로 유입되는 하수량을 정량제어 할수있도록한오리피스형 유량조절장치를 제공하는데 목적임.'),
    ('5', '슬러지 탈수적치장치', '특허', 1, '20070601', '상하수도', '제10-2007-0053870호', '제0874615호', '20270601', '∘본 발명은 하수관에 퇴적되어 있는 슬러지를 준설기로 준설한 후 작업장 부근에서 준설 슬러지를 악취발산없이 탈수하고 일시적으로 보관함으로써 최종처분이 용이하게 하기 위한 장치를 구성하여 작업자의 환경개선은 물론 준설 슬러지의 악취로부터 주민을 보호하고 준설작업에 수반되는 주변도로의 불결함을 미연에 막을 수 있다.'),
    ('6', '침사 및 부유물 제거용 수처리장치', '특허', 1, '20070713', '상하수도', '제10-2007-0070700호', '제0913526호', '20270713', '∘본 발명은 원심력을 이용하여 하수에 포함된 토사를 제거할 뿐만 아니라 하수에 부유하는 부유물도 쉽게 제거할수 있게된다. 이에 따라 침사지 후단 관로의 토사 퇴적에 따른 유지관리가 용이하게 되며 결과적으로는 방류수역 및 침수에 대한 안정성을 도모할 수 있게된다.'),
    ('7', '폴리우레탄 디스크를 이용한 지진격리장치', '특허', 2, '20070906', '도로', '제10-2007-0090464호', '제0826279호', '20270906', '∘본발명은 탄성이 우수한 고분자재료로 알려져 있는 폴리우레탄 디스크를 이용한 지진격리장치에 관한 것이다.본 발명의 지진경리장치는 강도 및 탄성을 개선할 수 있으며 제조상의 편리성을 확보할 수 있을뿐만 아니라 회전 거동을 확보할 수 있다. 또한 지진 격리장치의 보수 및 유지를 용이하게 할 수 있다.'),
    ('8', '옹벽전면의 녹화를 이용한 조립식 보강토 옹벽', '특허', 2, '20080508', '도로', '제10-2008-0043063호', '제0889257호', '20280508', '∘본 발명에 의한 옹벽 전면의 녹화를 이용한 조립식 보강토 옹벽 및 이 시공방법에 의하면, 철망지지 및 연결수단을 통해 철망을 지면에 대해 경사지게 설치함과 아울러 철망과 보강재를 연결하여 보강토 옹벽을 시공함으로써 보강토 옹벽의 전면을 녹화할 수 있고 보강토 옹벽의 전면부의 유실을 막을 수 있으므로 공기를 단축할 수 있고 보강토 옹벽의 붕괴와 우실에 따른 막대한 보수비용을 절감함과 아울러 안전사고를 예방할 수 있다.'),
    ('9', '오염 처리용 담체 제조장치 및 제조방법', '특허', 3, '20081126', '상하수도', '제 10-2008-0118066호', '제1075577호', '20281126', '∘본 발명은 담체제조장치 및 담체제조방법과이에의해제조된담체에관한것이다.본담체제조장치는,천연물질과고분자물질을포함하는혼련및압출되는제1압출기와;비중이소정이하인고분자물질이압출되며,상기제1압출기토출구의내경에배치되는토출구를갖는제2압출기를포함한다.상기제1및제2압출기는,각각실린더와,상기실린더내에수용되어상기제1혼합물을혼합하는스크류와,상기스크류를구동하기위한구동부를포함한다.상기제1압출기토출구의외측에는,상기담체의 절단을 위한 절단장치가 설치 되어있다. 이에 의해, 생물친화성이 우수하고 비중이 낮은 담체를 제조할수있게됨으로써, 이담체를바이오필터에 적용하여바이오매스조절을 용이하게 하면서오. 폐수 및 대기오염을 고효율로 처리할수있다. '),
    ('10', '혼합형 빗물 저류조', '특허', 5, '20100525', '상하수도', '제 10-2010-0048851호', '제1030605호', '20300525', '∘본 발명은 지하에 설치되는 빗물 저류조에 관한 것으로, 더욱 상세하게는 플라스틱 블럭을 적층하여 저수공간 확보하는 저류조의 하부에 주철판넬을 이용하여 유지관리를 위한 작업자의 이동 통로를 확보함으로써 저수조 바닥에 침적된 오염물질들을 수시로 청소하는 등 유지관리 작업의 실시가 가능한 혼합형 빗물 저류조에 관한 것이다.'),
    ('11', '에너지 절약형 중수처리 및 공급시스템', '특허', 1, '20090925', '상하수도', '제 10-2009-0091305호', '제1133370호', '20290925', '∘본 발명은 생활하수 중 오염도가 낮은 하수를 정화하여 재이용하는 생활하수 중수도 시스템에 관한 것으로서, 더욱 상세하게는 고층건물의 중간층에 생활하수를 정화하기 위한 중수처리시설을 설치하고, 그 상부 층에서 발생하는 오염도가 낮은 생활하수를 집수하여 정화한 후, 그 상부 층과 하부 층으로 중수를 나누어 공급하는 에너지 절약형 중수처리 및 공급시스템에 관한 것이다. 본 발명의 에너지 절약형 중수처리 및 공급시스템은, 아파트, 사무용 및 상업용 빌딩 등과 같은 고층건물의 중간층에 설치되어 오염도가 낮은 생활하수를 정수하는 중수처리시설과, 상기 중수처리시설이 설치된 중간층의 상부 층에서 배수되는 생활하수 중 오염도가 낮은 생활하수를 상기 중수처리시설로 공급하는 원수집수시설과, 상기 중수처리시설이 설치된 중간층의 상부 층으로 상기 중수처리시설에서 처리한 중수를 공급할 수 있도록 설치된 상향중수공급시설과, 상기 중수처리시설이 설치된 중간층의 하부 층으로 상기 중수처리시설에서 처리한 중수를 공급할 수 있도록 설치된 하향중수공급시설을 포함하여 구성된다.'),
    ('12', '도로노면 마찰계수와 전방 도로 상황 정보를 이용한 도로교통위험등급 제공방법 및 장치와 그 시스템', '특허', 1, '20091130', '도로', '제10-2009-0117081호', '제1102819호', '20291130', '본 발명은 도로변에 설치된 국지형 시스템에서 도로노면상태(예: 습윤/수막/결빙/눈/낙하물)에 해당하는 노면마찰계수와, 전방의 교통상태정보, 기후정보, 속도정보 등을 복합적으로 고려하여 전방 도로 상황의 위험등급을 산정한 후 안전지수(Safety Index) 정보 형식으로 주행 중인 차량 및 도로안내전광판(Variable Message Sign-VMS)에 제공하여 안전운전을 유도하는 도로노면 마찰계수와 전방 도로 상황 정보를 이용한 도로교통위험등급 제공방법 및 장치와 그 시스템에 관한 것으로, 전방의 교통상태를 현장에서 실시간으로 제공해 안전운전을 유도하여 사고를 사전에 예방한다.'),
    ('13', '상대속도를 고려한 실시간 안전거리 및 정지거리 바 산출 알고리즘을 이용한 적정차량간격 정보제공시스템', '특허', 1, '20100205', '도로', '제10-2010-0010937호', '제1102818호', '20300205', '본 발명은 적정차량간격 정보제공시스템에 관한 것으로서, 본 발명의 일 측면에 따르면 실시간으로 선,후행차량간의 적정차량간격정보를 제공하는 시스템에 있어서, 도로의 노면상태를 실시간으로 감지하는 노면상태감지부; 노면상태감지부로부터 전송된 노면상태정보를 수신하고, 선,후행차량이 위치한 지점의 도로상태정보 및 노면상태정보를 후행차량으로 전송하는 서버부; 후행차량내에 설치되며, 안전거리 및 정지거리 산정에 필요한 주행상태정보를 산출하는 주행상태산출부; 및 노면상태정보, 도로상태정보 및 주행상태정보를 이용하여 운전자에게 안전거리 및 정지거리 정보를 제공하는 정보제공장치;를 포함하여 이루어지는 것을 특징으로 하는 상대속도를 고려한 실시간 안전거리 및 정지거리 바 산출 알고리즘을 이용한 적정차량간격 정보제공시스템이 제공된다.'),
    ('14', '레이저 빔을 이용한 안개 발생 경고 표시장치 및 그 동작방법', '특허', 1, '20100910', '도로', '제10-2010-0088997호', '제1185602호', '20300910', '본 발명은 안개 발생 경고 표시장치에 관한 것으로 도로변에 설치하여 안개 발생시 작은 물방울 입자에 반사되는 가이드라인을 표시하여 운전자로 하여금 안전운전을 할 수 있도록 유도하여 안개로 인한 사고를 사전에 예방하는데 목적이 있다.'),
    ('15', '관라이닝재 반전장치 및 이를 이용한 관라이닝재의 반전방법', '특허', 2, '20100520', '상하수도', '제10-2010-0047619호', '제1190799호', '20300520', '서로 분리 및 결합 가능한 하부드럼과 하부드럼을 가지는 원통드럼과, 원통드럼의 내부에 회전 가능하게 설치되어 노후 관로 내부를 보수할 관라이닝재가 권취되는 회전축과, 회전축의 양측에 설치되어 회전축에 권취되는 관라이닝재를 가이드하는 가이드릴과, 하부드럼의 후방의 하부에 개폐 가능하게 설치되어 원통드럼 내부로 권취되는 관라이닝재가 유입되는 관라이닝재 삽입부, 하부드럼의 후방의 상부에 설치되며 원통드럼 내부에 권취된 관라이닝재를 노후 관로의 보수를 위해 반전시켜 배출시키기 위한 관라이닝재 배출부, 원통드럼에 개폐 가능하게 설치되어 원통드럼의 내부를 확인할 수 있는 점검용 도어유닛 및 원통드럼 내부로 가압공기를 공급하기 위한 가압공기 공급구를 포함하는 관라이닝재 반전장치 및 이를 이용한 관라이닝재 반전방법이 개시된다.'),
    ('16', '관라이닝재 반전장치 및 이를 이용한 관라이닝재의 반전방법', '특허', 2, '20100520', '상하수도', '제10-2010-0047622호', '제1190800호', '20300520', '내부에 노후 관로를 보수할 관라이닝재를 권취하기 위한 회전축이 설치되는 밀폐형 원통드럼과, 원통드럼의 후방 하부에 장방형으로 형성되며 회전축에 권취될 관라이닝재가 삽입되는 관라이닝재 삽입부와, 원통드럼의 관라이닝재 삽입부의 상부에 설치되어 회전축에 권취된 관라이닝재를 반전배출시키기 위한 관라이닝재 배출부와, 원통드럼에 개폐 가능하게 설치되어 원통드럼의 내부를 확인할 수 있는 점검용 도어유닛 및 원통드럼 내부로 가압공기를 공급하기 위한 가압공기 공급구를 포함하는 관라이닝재 반전장치 및 이를 이용한 관라이닝재 반전방법이 개시된다'),
    ('17', '눈부심 위험등급 판정 방법 및 눈부심 위험 고지 시스템', '특허', 1, '20101015', '도로', '제10-2010-0100934호', '제1235876호', '20301015', '본 발명은 태양광에 의한 눈부심 위험을 사전에 운전자에게 고지하여 위험을 저감시키고자 하는 눈부심 위험등급 판정 방법. 및 눈부심 위험 고지 시스템에 관한 것으로, GPS장치와 경사계로 운전자의 위치와 경사도를 구하거나, 도로설계 자료가 있는 경우 도로설계자료를 바탕으로 위치정보와 차량의 경사도를 계산하고 운전자의 시야각을 상하좌우 각도의 크기에 따라 입력 위험등급을 결정하며, GPS의 날짜와 시간 혹은 입력된 날짜와 시간에 태양의 방위각과 고도를 계산하고, 계산된 태양의 위치가 위험등급에 해당하는 범위 내에 존재하는 경우 위험구간 후보로 저장하고, 일조시간 DB가 존재하고 일조시간이내에 존재하게 될 경우 해당하는 위험등급의 위험구간으로 판정하고, 그렇지 않은 경우는 위험하지 않은 것으로 판정한다. 그리고, 일조시간 DB가 존재하지 않는 경우는 운전자 위치와 태양과의 가상의 반무한 직선을 생성한 후 3차원 GIS 데이터를 검색하여 교차여부를 판단하여 교차점이 없는 경우는 해당위험등급의 위험구간으로 선정하고, 교차점이 있는 경우는 위험구간에서 제외하며, 결정된 해당위험등급의 위험구간으로 판정된 구간 중에서 그 위치가 터널 혹은 지하차도 시설물이 전후 구간에 존재하는 경우에 위험등급을 상향시켜 고지함으로써 운전자에게는 안전운전을 유도하고, 도로설계자 및 조사자의 경우에는 설계개선이 가능하도록 한다.'),
    ('18', '연약지반용 확장 천공 장치 및 이를 이용한 연약지반 보강공법', '특허', 4, '20140228', '도로', '제10-2014-0024609호', '제1481123호', '20340228', '본 발명은 연약지반용 확장 천공 장치 및 이를 이용한 연약지반 보강 공법에 관한 것으로, 연약지반 안에 확장형 앵커체를 설치하여 보강하되 선단부에 타구간보다 단면적이 큰 선단확장공을 선시공한 후 이 선단확장공을 갖는 확장형 앵커공에 확장형 앵커체가 설치되도록 함으로써 선단부의 붕괴를 유발하지 않고 확장형 앵커체를 시공하고 이로써 선단부에서 큰 정착력을 확보하여 연약지반을 견고하게 보강함을 목적으로 한다.'),
    ('19', '우각부 강결성능이 개선된 PSC거더 및 이를 이용한 라멘 또는 박스형 구조물 시공방법', '특허', 3, '20141010', '도로', '제10-2014-0136846호', '제1551451호', '20341010', '본 발명은 우각부 강결성능이 개선된 PSC거더 및 이를 이용한 라멘 [0001] 또는 박스형 구조물 시공방법에 관한 것이다. 더욱 구체적으로 라멘교에 있어서 PSC거더 양 벽체부에 강결시켜 시공함으로써 우각부에 위치한 PSC거 더의 양 단부에 발생하는 압축력과 인장력을 우각부 콘크리트에 보다 효과적으로 전달할 수 있는 우각부 강결 성능이 개선된 PSC거더 및 이를 이용한 라멘 또는 박스형 구조물 시공방법에 대한 것이다.'),
    ('20', '교량받침 변형량 측정장치', '특허', 1, '20200610', '도로', '제10-2020-0070247호', '제2199771호', '20400610', '본 발명의 실시예에 따르면, 하부몸체와 상부몸체를 상대이동시켜 배치시키는 것만으로 교량받침의 변형량을 정확하며 용이하게 측정할 수 있다. 나아가, 한 쌍의 하부지지암의 교량받침의 하단부에 밀착되고, 한 쌍의 상부지지이 교량받침의 상단부에 밀착되도록 제공됨으로써, 측정과정에 흔들림 등이 방지되어 보다 효과적으로 측정할 수 있다.'),
    ('21', '구조물 단차 측정 장치', '특허', 1, '20200727', '도로', '제10-2020-0092846호', '제2197558호', '20400727', '본 발명의 작업자에게 편리를 제공하고 정확한 측정이 가능한 구조물 단차 측정 장치를 제공하는 것이다. 구조물 단차 측정 장치가 제 1 단차면와 제 2 단차면에 고정 설치되기 때문에 작업자는 줄자를 휴대할 필요가 구조물 단차 측정 장치가 설치된 현장에서 제 1 고정 부재와 교차하는 스케일 부재의 눈금을 읽어 단차를 측정할 수 있어 편리하다.'),
    ('22', '버팀보용 굴절지지대', '특허', 4, '20180705', '도로', '제10-2018-0078312호', '제2095480호', '20380705', '본 발명은 흙막이 공사에서 선행하중공법에 의한 버팀보 설치시 토류벽을 지지하는 버팀보를 쉽게 해체할 수 있도록 버팀보와 토류벽 사이에 위치하는 굴절지지대의 지지링크를 쉽게 고정 및 해체할 수 있어 작업성 및 안전성 향상이 가능한 버팀보용 굴절지지대에 대한 것이다.'),
    ('23', '안전난간 구조체', '특허', 2, '20210315', '도로', '제10-2021-0033304호', '제2325549호', '20410315', '안전난간 구조체가 개시되며, 상기 안전난간 구조체는, 주난간의 내측의 기초부 또는 주난간의 내측 하단에 하측이 고정되고 상향 연장되는 차단막; 상기 차단막의 상단으로부터 상기 주난간의 외측으로 경사지게 상향 연장되는 광투과부재; 상기 주난간의 상단과 연결되고, 상기 광투과부재의 외측을 지지하도록 상기 광투과부재의 형상에 대응하여 경사지게 상향 연장되는 지지부재; 상기 차단막을 상기 주난간에 고정하는 제1 고정부; 및 상기 광투과부재를 상기 지지부재에 고정하는 제2 고정부를 포함하되, 상기 차단막에는, 통풍은 허용하되 발돋움은 허용하지 않는 크기의통풍구 복수개가 형성되고, 상기 광투과부재는, 상측 끝단에 대하여 상기 주난간의 내측에 위치한 사람의 파지가 허용되지 않는 길이만큼 외측으로 연장되고, 상기 주난간은, 상기 지지부재와 체결 또는 접합을 통해 연결되는 별도 난간이거나, 상기 지지부재와 일체적으로 구비되는 일체형 난간이다.'),
    ('24', '공동주택 지하주차장의 천장 방수구조', '특허', 1, '20210319', '도로', '제10-2021-0035758호', '제2344696호', '20410319', '천장 방수구조가 개시되며, 상기 천장 방수구조는, 적어도 일부가 상기 천장의 하측으로 노출되도록 상기 천장에 구비되는 액체 흡수 부재; 및 상기 천장 상에 구비되는 액체 흡수 시트를 포함하되, 상기 액체 흡수 부재 및 상기 액체 흡수 시트는, 상기 천장의 누수의 적어도 일부를 흡수하고, 상기 액체 흡수 부재는, 액체를 흡수 가능한 액체 흡수 직물을 포함하며, 액체 흡수 직물은, 나선 중심을 따라 액체를 흡수하는 모세관 현상이 유도되도록, 복수개를 나선형으로 꼰 형태로 구비될 수 있다.'),
    ('25', '사용자 단말 기반의 지능형 도로 정보 수집 장치 및 방법', '특허', 1, '20220303', '도로', '제10-2022-0027187호', '제2426233호', '20420303', '사용자 단말 기반의 지능형 도로 정보 수집 장치 및 방법이 개시되며, 본원의 일 실시예에 따른 사용자 단말 기반의 지능형 도로 정보 수집 방법은, (a) 제1차량에 구비되는 사용자 단말로부터 상기 제1차량의 주행 도중 수집되는 측정 데이터를 수신하는 단계, (b) 상기 측정 데이터에 기초하여 상기 제1차량이 주행한 대상 도로와 연계된 위험 이벤트의 발생을 감지하는 단계 및 (c) 상기 대상 도로를 주행하거나 상기 대상 도로를 향하여 주행할 것으로 예측되는 제2차량에 구비되는 사용자 단말로 상기 위험 이벤트에 대응하여 생성된 경고 정보를 전송하는 단계를 포함할 수 있다.'),
    ('26', '꼬리물기 방지를 위한 도로 모니터링 및 신호 제어 장치 및 방법', '특허', 1, '20220303', '도로', '제10-2022-0027176호', '제2426499호', '20420303', '꼬리물기 방지를 위한 도로 모니터링 및 신호 제어 장치 및 방법이 개시되며, 본원의 일 실시예에 따른 꼬리물기 방지를 위한 도로 모니터링 및 신호 제어 방법은, (a) 미리 설정된 간섭 영역을 포함하는 대상 도로를 주행하는 차량이 상기 간섭 영역을 통과한 후 위치하게 되는 모니터링 영역에 대한 차량 통행량 정보를 획득하는 단계, (b) 상기 차량 통행량 정보에 기초하여 상기 모니터링 영역에서의 차량 정체 수준을 예측하는 단계 및 (c) 상기 예측 결과에 기초하여 상기 간섭 영역에 진입하기 전 영역인 제어 영역에 위치하는 차량에 대하여 적용되는 신호 정보를 결정하는 단계를 포함할 수 있다.'),
    ('27', '하수처리장에서 연료전지의 셀오프가스 재활용시스템', '특허', 3, '20210913', '상하수도', '제10-2021-0121795호', '제2433217호', '20410913', '본 발명은 원료가스로부터 황을 처리하는 전처리부; 황이 제거된 원료가스를 공급받아 수소로 개질하여 개질수소연료를 생성하는 개질부; 상기 개질부에서 개질수소연료를 공급받아 전기를 생산하고, 셀오프가스를 부산시키는 연료전지; 하수를 처리하면서 방류수를 배출하고, 상기 연료전지로부터 발생되는 폐열을 공급받아 에너지원으로 사용하는 하수처리장; 상기 셀오프가스를 공급받고 상기 방류수를 공급받아 열교환에 의해 수분이 제거된 셀오프가스를 배출하는 응축부; 수분이 제거된 셀오프가스를 유입받아 냉,난방에너지를 상기 하수처리장으로 공급하는 냉난방부;를 포함하는 것을 특징으로 하는 하수처리장에서 연료전지의 셀오프가스 재활용시스템에 관한 것이다.'),
    ('28', '비점 오염 저감용 필터를 구비한 프리캐스트 배수 트렌치', '특허', 1, '20211001', '상하수도', '제10-2021-0130653호', '제2447229호', '20411001', '비점 오염 저감용 필터를 구비한 프리캐스트 배수 트렌치가 개시되며, 상기 비점 오염 저감용 필터를 구비한 프리캐스트 배수 트렌치는, 내부에 길이 방향을 따라 주배수로가 형성되고, 길이 방향 일단에 상기 주배수로로부터 하측으로 함몰되는 함몰부가 형성되며, 길이 방향 타단에 제1 필터부가 구비되고, 상기 함몰부의 저면 상에 제2 필터부가 구비되는 주배수부를 포함한다.'),
    ('29', '지능형 횡단보도 보행 안전지원 장치 및 방법', '특허', 1, '20211001', '도로', '제10-2021-0130563호', '제2452124호', '20411001', '지능형 횡단보도 보행 안전지원 장치 및 방법이 개시되며, 본원의 일 실시예에 따른 지능형 횡단보도 보행 안전지원 방법은, (a) 횡단보도 상에서 보행하거나 상기 횡단보도와 이웃한 대기 영역에 위치하는 대상 보행자를 감지하고, 상기 대상 보행자의 보행상태 정보를 획득하는 단계, (b) 상기 횡단보도로 접근하도록 주행하는 대상 차량을 식별하고, 상기 대상 차량의 주행상태 정보를 획득하는 단계, (c) 상기 보행상태 정보 및 상기 주행상태 정보에 기초하여 상기 횡단보도와 연계된 위험도를 연산하는 단계 및 (d) 상기 위험도에 기초하여 경고 신호를 출력하는 단계를 포함할 수 있다.'),
    ('30', '강성증대 엄지말뚝을 이용한 자립 장치 및 이의 시공 방법', '특허', 1, '20220302', '도로', '제10-2022-0027030호', '제2499826호', '20420302', '강성증대 엄지말뚝을 이용한 자립 장치가 개시되며, 상기 강성증대 엄지말뚝을 이용한 자립 장치는, 간격을 두고 서로 이웃하게 배치되고, 각각이 전면 플랜지, 후면 플랜지 및 전면 플랜지와 후면 플랜지를 연결하는 웨브를 포함하며, 각각의 하부의 근입부가 지반의 근입홀에 삽입되어 각각의 상부의 노출부가 전방의 굴착부로 노출된 빔 구조체 복수 개; 배면 토사를 지지하도록, 상기 복수의 빔 구조체의 상기 노출부 사이를 차단하게 구비되는 토류판 복수 개; 각각이 긴장된 상태로 상단이 복수의 빔 구조체 각각의 상기 후면 플랜지에 정착되고 하단이 상기 복수의 빔 구조체 각각의 상기 전면 플랜지에 정착되도록 상기 복수의 빔 구조체 각각에 대하여 구비되는 긴장재 복수개; 상기 복수의 빔 구조체 각각에 대해 구비되되, 각각이 상기 노출부의 하부에 장착되는 장착 구조부 및 상기 장착 구조부에 결합되어 상기 노출부의 하부의 전방에서 상기 굴착부의 저면에 접촉되게 배치되는 팽창성 탄성부를 포함하고 상기 빔 구조체를 상기 굴착부의 저면에 대하여 지지하는 지지 구조체 복수 개를 포함한다.'),
    ('31', '슈미트 해머 기록지 이미지 프로세싱용 장치 및 방법', '특허', 1, '20220921', '도로', '제10-2022-0119079호', '제2499078호', '20420921', '내부 공간에 기록지가 상호 연결되게 감긴 제1 릴과 제2 릴이 횡 방향으로 간격을 두고 장착된 하우징을 포함하는 슈미트 해머의 상기 기록지에 대한 이미지 프로세싱용 장치로서, 본원의 일 실시예에 따른 슈미트 해머 기록지 이미지 프로세싱용 장치는, 상기 내부 공간이 외부에 개방되도록 내부 공간을 덮는 커버가 열린 개구 상태에서, 상기 하우징의 개구 영역을 덮도록 배치되는 마커 플레이트부를 포함하고, 상기 마커 플레이트부는, 광 투과성을 가지고 상기 개구 영역을 덮도록 구비되는 광 투과 플레이트 부재; 상기 제1 릴에 감겨 있는 기록지의 폭 방향 양측에 구비되는 일단 디스크 및 타단 디스크 각각의 일부와 맞물리도록 상기 광 투과 플레이트 부재로부터 상기 내부 공간 측으로 돌출되는 제1 일단 맞물림 부재와 제1 타단 맞물림 부재; 및 상기 제2 릴에 감겨 있는 기록지의 폭 방향 양측에 구비되는 일단 디스크 및 타단 디스크 각각의 일부와 맞물리도록 상기 상기 광 투과 플레이트 부재로부터 상기 내부 공간 측으로 돌출되는 제2 일단 맞물림 부재와 제2 타단 맞물림 부재를 포함하고, 상기 광 투과 플레이트 부재에는 상기 마커 플레이트부가 배치된 상태에서 상기 기록지에 대한 이미지 획득시 포함되는 레퍼런스 마커가 표시될 수 있다.'),
    ('32', '교량 받침의 안전 진단용 변위 측정 장치', '특허', 1, '20220905', '도로', '제10-2022-0111870호', '제2571428호', '20420905', '교량 받침의 안전 진단용 변위 측정 장치가 개시되며, 상기 교량 받침의 안전 진단용 변위 측정 장치는, 상기 교량 받침을 향하는 전방을 향해 거리 측정기가 안착 및 고정될 수 있도록 구비되는 측정기 받침대; 상기 측정기 받침대가 상하 방향을 따라 이동 가능한 내부 공간을 가지되 상기 내부 공간은 상기 전방 및 상향으로 개구되게 형성되고, 상기 측정기 받침대의 상하 방향 이동을 가이드하도록 상기 측정기 받침대와 맞물림 결합되도록 제공되는 하우징; 및 상기 측정기 받침대를 상기 하우징에 대하여 원하는 높이에 선택적으로 고정하도록 구비되는 받침대 고정부를 포함한다.'),
    ('33', '안전진단 재하시험 위치 유도장치', '특허', 1, '20230331', '도로', '제10-2023-0042713호', '제2572877호', '20430331', '안전진단 재하시험 위치 유도장치가 개시되며, 상기 안전진단 재하시험 위치 유도장치는, 정적 재하 지점보다 교량 종 방향 일측에 배치되되, 교량 횡 방향을 따라 나란하게 제1 간격을 두고 배치되는 2개의 도달 광 표시부; 상기 정적 재하 지점보다 교량 종 방향 일측에 배치되되, 교량 횡 방향을 따라 나란하게 제2 간격을 두고 배치되는 2개의 가이드 광 조사부로서, 각각이 상기 정적 재하 지점보다 교량 종 방향 타측인 교량 표면 상에 교량 종 방향을 따라 종 방향 간격을 두도록 미리 설정된 복수의 가이드 지점을 향해 가이드 광을 조사하도록 제공되는 상기 2개의 가이드 광 조사부; 및 상기 재하 차량의 전면에 차량 폭 방향으로 나란하게 상기 제1 간격을 두고 설치되어 각각이 차량 전방 중 하향 경사 방향으로 차량 광을 조사하도록 제공되는 2개의 차량 광 조사 유닛을 포함하되, 상기 2개의 도달 광 표시부와 상기 2개의 차량 광 조사 유닛은, 상기 재하 차량이 상기 정적 재하 지점에 도달하기까지의 미리 설정된 이동 구간에 대하여 상기 재하 차량의 전진 방향이 교량 종 방향 일방과 어긋나는 비정상 진입 상태에서, 상기 2개의 차량 광 조사 유닛 각각으로부터 조사된 차량 광 중 하나 이상이 상기 2개의 도달 광 표시부를 벗어나게 조사되도록 구비된다.'),
    ('34', '비개착 추진형 굴진 장비, 이를 이용한 비개착 추진형 굴진 공법, 및 비개착 추진형 굴진 공법을 포함하는 비개착 복합 굴진 공법', '특허', 2, '20221118', '상하수도', '제10-2022-0155152호', '제2573829호', '20421118', '이물질 유입 방지 장치가 개시되며, 상기 이물질 유입 방지 장치는, 상기 간격 부분의 상측에서 상기 간격 부분을 덮으며 종 방향으로 연장 배치되고, 횡 방향 일측부는 상기 제1 슬래브에 접촉되고, 횡 방향 타측부는 상기 제2 슬래브에 접촉되는 덮개 판넬; 및 상기 덮개 판넬을 상기 간격 부분에 대하여 고정하는 고정 구조체를 포함하되, 상기 고정 구조체는, 상기 덮개 판넬 상에 배치되는 두부 및 상기 두부로부터 상기 덮개 판넬을 관통하여 상기 덮개 판넬의 하측으로 연장되는 몸체를 볼트 부재; 상단이 상기 몸체의 하단과 연결되어 상기 간격 부분의 하측으로 연장되는 연장 부재; 상기 간격 부분의 하측에서 상기 연장 부재 감싸며 배치되어 상기 제1 슬래브 및 상기 제2 슬래브에 상측으로 지지되게 배치되는 지지 부재; 상기 지지 부재의 하측에서 상기 연장 부재를 감싸며 구비되는 너트 부재; 및 상기 지지 부재와 상기 볼트 부재 사이에서 탄성 압축된 상태로 배치되어 탄성 압축력으로 상기 지지 부재를 상향 가압하게 구비되는 탄성 부재를 포함한다.'),
    ('35', '보조파일 탈착장치', '특허', 6, '20230428', '도로', '제10-2023-0055878호', '제2599315호', '20430428', '보조파일 탈착장치가 개시된다. 상기 보조파일 탈착장치는 하부파일의 상단에 고정되는 원형의 제1 고정판, 상기 제1 고정판의 원주 방향으로 배열되는 복수의 제1 체결고리, 상기 복수의 제1 체결고리와 이격되며 상기 제1 고정판의 지름 방향으로 서로 이격되게 구비되며 중공의 원통 구조로 구비되는 한 쌍의 제1 정렬가이드를 포함하는 하부파일 탈착기구; 보조파일의 하단에 고정되는 원형의 제2 고정판, 상기 제2 고정판의 직경에 대응하는 외경을 갖고 상기 제2 고정판의 가장자리에서 일정 높이로 돌출되는 환형테두리, 상기 환형테두리 내에서 상기 제2 고정판의 원주 방향으로 상기 복수의 제1 체결고리와 동일 개수로 배열되는 복수의 제2 체결고리, 상기 복수의 제2 체결고리보다 안쪽 위치에서 상기 제2 고정판의 중심을 축으로 하여 회전 가능하게 상기 제2 고정판의 중심부에 체결되는 고리탈착부재, 상기 고리탈착부재를 상기 제2 고정판의 중심부에 체결시키는 고리탈착부재 체결부재, 상기 복수의 제2 체결고리와 이격되며 축 구조로 구비되며 상기 제2 고정판의 지름 방향으로 서로 이격되되 상기 한 쌍의 제1 정렬가이드와 동일 간격으로 이격되며 상기 보조파일을 상기 하부파일에 동축으로 위치시킬 때 상기 한 쌍의 제1 정렬가이드(103)에 체결되는 한 쌍의 제2 정렬가이드(230)를 포함하는 보조파일 탈착기구; 상기 보조파일의 중공으로 삽입되어 하단부가 상기 고리탈착부재에 연결되고, 정역 회전하여 상기 고리탈착부를 정역 회전시키는 고리탈착부재 작동축; 및 상기 고리탈착부재 작동축의 상단부에 연결되어 상기 고리탈착부재 작동축을 정역 회전시키는 작동축 구동장치를 포함하고, 상기 고리탈착부재는, 상기 제2 고정판의 중심부에 상기 제2 고정판의 중심을 축으로 하여 회전 가능하게 상기 제2 고정판의 중심부에 체결되며, 일측에 맞물림기어가 형성되는 회전링; 및 상기 회전링과 일체를 이루어 상기 회전링의 원주면으로부터 돌출되고, 상기 회전링의 원주방향으로 상기 복수의 제1 체결고리 및 상기 복수의 제2 체결고리와 동일 개수로 배열되며, 평상시 말단이 상기 제2 체결고리에 삽입되며, 상기 제2 체결고리가 상기 제1 체결고리와 이웃하여 위치한 상태에서 상기 회전링이 정방향 회전되면 말단이 상기 제2 체결고리로 삽입되는 복수의 탈착레버를 포함하고, 상기 고리탈착부재 체결부재는, 상기 회전링의 중심에 삽입되는 링체결축부, 상기 링체결축부의 상단부에 상기 회전링의 내경 이하의 외경을 갖도록 형성되며 원주 방향을 따라 나사축 관통구멍이 다수 배열되는 환형플레이트부, 상기 환형플레이트부의 상면의 가장자리로부터 돌출되며 상기 회전링의 내경보다 큰 외경을 갖도록 형성되고 상기 링체결축이 상기 회전링의 중심에 삽입될 때 상기 환형플레이트부와 함께 상기 회전링의 중심부를 덮는 회전링커버플랜지를 포함하는 회전링 체결부재; 헤드부가 상기 제2 고정판에 고정되어 나사축이 상기 제2 고정판으로부터 돌출되고, 상기 회전링 체결부재가 상기 회전링에 체결될 때 상기 나사축이 상기 나사축 관통구멍을 관통하여 상기 환형플레이트부의 상면으로 노출되는 회전링 체결부재 고정볼트; 및 상기 환형플레이트부의 상면에서 상기 회전링 체결부재 고정볼트에 결합되는 고정너트를 포함하고, 상기 작동축의 하단부에는 상기 맞물림 기어에 치합되는 구동기어가 구비되는 것을 특징으로 한다.'),
    ('36', '교량 받침의 안전 진단용 변위 측정 장치', '특허', 1, '20230818', '도로', '제10-2023-0108219호', '제2698259호', '20430818', '교량 받침의 안전 진단용 변위 측정 장치가 개시되며, 상기 교량 받침의 안전 진단용 변위 측정 장치는, 상기 교량 받침을 향하는 전방을 향해 거리 측정기가 안착 및 고정될 수 있도록 구비되는 측정기 받침대; 상기 측정기 받침대가 상하 방향을 따라 이동 가능한 내부 공간을 가지되 상기 내부 공간은 상기 전방 및 상향으로 개구되게 형성되고, 상기 측정기 받침대의 상하 방향 이동을 가이드하도록 상기 측정기 받침대와 맞물림 결합되도록 제공되는 하우징; 및 상기 측정기 받침대를 상기 하우징에 대하여 원하는 높이에 선택적으로 고정하도록 구비되는 받침대 고정부를 포함한다.'),
    ('37', 'X바 고정형 모듈러 기초 구조물 및 이의 시공 방법', '특허', 1, '20230331', '도로', '제10-2023-0042714호', '제2728490호', '20430331', 'X바 고정형 모듈러 기초 구조물이 개시되며, 상기 X바 고정형 모듈러 기초 구조물은, 상기 모듈러 기초 구조물의 종 방향으로 연속되는 제1 패턴부가 상면에 대하여 형성된 하부 블록을 포함하는 하부 블록부; 및 상기 종 방향으로 연속되는 제2 패턴부가 상기 제1 패턴부와 맞물리게 하면에 대하여 형성된 상부 블록을 포함하고, 상기 하부 블록부 상에 배치되는 상부 블록부; 상기 상부 블록부를 상기 하부 블록부에 고정하는 복수의 바를 포함하되, 상기 복수의 바는, 종 방향에서 바라보았을 때 X자 형태로 서로 교차되도록 종 방향을 따라 간격을 두고 번갈아 가며 배치되고, 상기 상부 블록부와 상기 하부 블록부 각각에는 상기 복수의 바가 설치되는 바 삽입구가 형성된다.')
)
INSERT INTO new_technology_developments (
    sequence_label,
    title,
    technology_type,
    applicant_count,
    application_date,
    target_field,
    application_no,
    registration_no,
    valid_until,
    summary,
    created_id,
    last_changed_id
)
SELECT
    sequence_label,
    title,
    technology_type,
    applicant_count,
    application_date,
    target_field,
    application_no,
    registration_no,
    valid_until,
    summary,
    'migration',
    'migration'
FROM source_rows source
WHERE NOT EXISTS (
    SELECT 1
    FROM new_technology_developments existing
    WHERE COALESCE(existing.registration_no, '') = COALESCE(source.registration_no, '')
      AND existing.title = source.title
);
